import { test, expect } from '@playwright/test';

test.describe('Modal Responsiveness', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-website-url.com');
    await page.getByRole('button', { name: 'Open Modal' }).click();
  });

  test('should display modal correctly on mobile screen size', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 }); // iPhone 8 size
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();
    await expect(modal).toHaveCSS('max-width', '100%');
    await expect(modal).toHaveCSS('width', '100%');
  });

  test('should close modal when close button is clicked', async ({ page }) => {
    await page.getByRole('button', { name: 'Close' }).click();
    const modal = page.getByRole('dialog');
    await expect(modal).not.toBeVisible();
  });
});
